CommitDate: Wed Jun 19 22:40:02 2024 +1200

    Bug 1881153 - Wait for status bar meteors to stop when waiting for connection idle. r=mkmelin
    This waits until the status bar progress meter is not active and not about to become active
    whenever promiseServerIdle is called. That should help prevent the status bar getting confused by
    multiple connections coming and going.

    Differential Revision: https://phabricator.services.mozilla.com/D214331

diff --git a/mail/base/content/mailWindow.js b/mail/base/content/mailWindow.js
index 1620a66db1f..1959ad9903b 100644
--- a/mail/base/content/mailWindow.js
+++ b/mail/base/content/mailWindow.js
@@ -346,6 +346,7 @@ nsMsgStatusFeedback.prototype = {
   _statusFeedbackProgress: -1,
   _statusLastShown: 0,
   _lastStatusText: null,
+  _timeoutDelay: ChromeUtils.isInAutomation ? 50 : 500,

   // unload - call to remove links to listeners etc.
   unload() {
@@ -509,7 +510,7 @@ nsMsgStatusFeedback.prototype = {
     ) {
       this._startTimeoutID = setTimeout(
         () => window.MsgStatusFeedback._startMeteors(),
-        500
+        this._timeoutDelay
       );
     }

@@ -564,7 +565,7 @@ nsMsgStatusFeedback.prototype = {
     ) {
       this._stopTimeoutID = setTimeout(
         () => window.MsgStatusFeedback._stopMeteors(),
-        500
+        this._timeoutDelay
       );
     }
   },
